  "preferred_configuration": {
    "prize_parts": [
      {
        "ballot_id": "B058",
        "laureates": [
          "Harald Rose",
          "Knut Urban",
          "Maximilian Haider"
        ],
        "citation": "For the invention and realization of spherical-aberration correction in electron microscopy, enabling atomic-scale imaging."
      }
    ]
  },
  "alternatives": [
    "B039",
    "B037"
  ],
  "statement": {
    "case_for": "Spherical-aberration correction overcame a basic limit of electron optics and made atomic-scale imaging and analysis broadly practical. This is a clear invention with a lasting experimental impact: the capability has been established in instruments used across materials research. Rose's correction concepts and Urban's and Haider's roles in implementation and demonstration form a coherent attribution spanning idea to working instrument.",
    "case_against": "The historical boundary between the original correction concepts and their practical realization needs careful checking. A three-person citation may not capture all contributors to the early instruments, and the broad impact of the technique does not by itself settle who made the original decisive contributions.",
    "responses": [
      {
        "member_id": "johansson-goran",
        "point": "Johansson argues that ultracold atoms in optical lattices established quantum simulation as a powerful method, with complementary contributions from Bloch, Greiner, and Zoller, while noting uncertainty about its broader impact.",
        "response": "I agree that this is a mature and consequential experimental platform. For this choice, the specific instrument invention and its broadly established capability make the prize boundary more concrete; the significance of quantum simulation relative to other ways of studying many-body systems remains a larger open question."
      },
      {
        "member_id": "eriksson-olle",
        "point": "Eriksson places spherical-aberration correction among important materials discoveries and finds Rose's design work and Urban's and Haider's implementation persuasive, while calling for care over the boundary between the original concepts and later realization.",
        "response": "I share that attribution concern. The concepts alone are not the full invention: practical correction required realization and experimental demonstration. The proposed trio captures those roles, but the historical record should establish that each person's contribution was decisive to the original working instruments."
      }
    ],
    "uncertainties": [
      "The priority and individual credit boundary between the original correction concepts and the first practical aberration-corrected instruments needs verification."
    ],
    "conflict_note": "I work in electron microscopy, giving me a professional field connection to B058; no personal or institutional connection to the credited researchers is apparent from the supplied profile."
  }
}
